import { useState } from 'react';
import {
  Badge,
  Divider,
  FormField,
  Heading,
  Page,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettingsValue {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsProps {
  defaultValue?: AppearanceSettingsValue;
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const INITIAL_VALUE: AppearanceSettingsValue = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

export default function AppearanceSettings({
  defaultValue,
  onChange,
}: AppearanceSettingsProps) {
  const [value, setValue] = useState<AppearanceSettingsValue>(
    defaultValue ?? INITIAL_VALUE,
  );

  const update = (patch: Partial<AppearanceSettingsValue>) => {
    const next = { ...value, ...patch };
    setValue(next);
    onChange?.(next);
  };

  const themeLabel =
    THEME_OPTIONS.find((option) => option.value === value.theme)?.label ?? '';

  return (
    <Page>
      <Stack gap="lg">
        <Stack direction="row" align="center" justify="between" gap="md">
          <Heading level={1}>Внешний вид</Heading>
          <Badge variant="neutral">{themeLabel}</Badge>
        </Stack>

        <FormField label="Тема" htmlFor="appearance-theme">
          <SegmentedControl
            id="appearance-theme"
            value={value.theme}
            options={THEME_OPTIONS}
            onChange={(theme: ThemeMode) => update({ theme })}
          />
        </FormField>

        <FormField
          label="Масштаб интерфейса"
          htmlFor="appearance-scale"
          hint={`${value.scale}%`}
        >
          <Slider
            id="appearance-scale"
            min={80}
            max={140}
            step={5}
            value={value.scale}
            onChange={(scale: number) => update({ scale })}
          />
        </FormField>

        <Switch
          checked={value.dense}
          label="Плотная вёрстка"
          description="Меньше отступов между элементами"
          onChange={(dense: boolean) => update({ dense })}
        />

        <Divider />

        <Stack gap="md">
          <Heading level={2}>Ещё</Heading>
          <Text tone="muted">Дополнительные параметры оформления</Text>

          <FormField label="Шрифт" htmlFor="appearance-font">
            <Select
              id="appearance-font"
              value={value.font}
              options={FONT_OPTIONS}
              onChange={(font: FontFamily) => update({ font })}
            />
          </FormField>
        </Stack>
      </Stack>
    </Page>
  );
}

